type Result<T, E> =
  | { ok: true; value: T }
  | { ok: false; error: E };

function parseJson<T>(raw: string): Result<T, SyntaxError> {
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch (e) {
    return { ok: false, error: e as SyntaxError };
  }
}

