import { ok, err, Result, ResultAsync } from 'neverthrow';

function parse(raw: string): Result<User, Error> {
  try { return ok(JSON.parse(raw) as User); }
  catch (e) { return err(e as Error); }
}

// Railway: .map aplica transformação só se ok
